// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, uint96 amount, uint8 nDeposits) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        uint256 n = bound(uint256(nDeposits), 1, 10);
        vm.deal(actor, uint256(amount) * n);
        for (uint256 i = 0; i < n; i++) {
            vm.prank(actor);
            (bool ok,) = address(c).call{value: amount}("");
            assertTrue(ok, "deposit should succeed");
        }
        assertEq(c.depositsCount(), n);
    }
}
